    async def jira_csv(self, jql: str, *, fields: Sequence[str] | None = None, dest: Path, backend: BackendKind | str | None = None) -> Path:
        """Export the issues of a JQL query as CSV (synthesized from search, or the product's native CSV export).

            When to use:
                A spreadsheet or a file hand-off is needed.

            Args:
                jql: JQL query. Validate unfamiliar JQL with `jira.jql.validate` first.
                fields: Columns to include (default: key, summary, status, ...).
                dest: File path to write the CSV to.
                backend: Force one backend ("rest", "mcp", "acli", ...). Default: the preset order. A cursor pins its backend.

            Returns:
                Path

            Raises:
                NoBackendAvailableError: No configured backend can serve this operation.

            Access: READ

            Example:
                >>> path = await client.exports.jira_csv("project = PROJ", dest=Path("issues.csv"))
        """
        return cast("Path", await self._call("export.jira.csv", JiraExporter, "export_issues_csv", jql, fields=fields, dest=dest, backend=backend))

